  5238|  const waitlist = byType['waitlist'] ?? 0;
  5239|  const investors = byType['investor'] ?? 0;
  5240|  const buyers = byType['buyer'] ?? 0;
  5241|  return Response.json({
  5242|    ok: true,
  5243|    members,
  5244|    waitlist,
  5245|    investors,
  5246|    buyers,
  5247|    total: await countCanonicalMembers(),
